import { IncentiveRewardInfo } from '@/types/incentive'
import { Block, TooltipIcon } from '@cetus/design'
import SingleTokenInfo from '@cetus/design/src/components/common/SingleTokenInfo'
import useDocumentSize from '@cetus/hooks/src/useDocumentSize'
import { HTextLabelBox } from '@cetus/ui-kit'
import { textEllipses, timeFormatUTC } from '@cetus/utils'
import { Button, Heading, HStack, Modal, ModalBody, ModalCloseButton, ModalContent, ModalHeader, ModalOverlay, Text, VStack } from '@chakra-ui/react'
import { formatEpoch } from './RewardTokenAndDuration'

type ConfirmModalProps = {
  totalAmount: string | number
  rewardList: IncentiveRewardInfo[]
  isOpen: boolean
  onClose: () => void
}

export default function ConfirmModal({ totalAmount, rewardList, isOpen, onClose }: ConfirmModalProps) {
  const textStyle = { fontSize: '14px' }
  const { size } = useDocumentSize()
  const modalH = rewardList?.length * 209 + (rewardList?.length - 1) * 8 > size?.h - 236 ? size?.h - 236 : 'unset'
  return (
    <Modal autoFocus={false} closeOnOverlayClick={false} returnFocusOnClose={false} isOpen={isOpen} onClose={onClose} isCentered>
      <ModalOverlay />
      <ModalContent>
        <ModalHeader>
          <Heading fontWeight="500" fontSize="16px">
            Add Incentives
          </Heading>
        </ModalHeader>
        <ModalCloseButton />
        <ModalBody p={{ base: '8px 12px !important', lg: '0  0px 16px !important' }}>
          <VStack w="100%" p="0 16px" align="flex-start" userSelect="none" minH="180px" h={modalH} overflow="auto">
            {rewardList?.map((rewardInfo: IncentiveRewardInfo, index: number) => (
              <Block borderRadius="16px" p="16px" key={index}>
                <HStack w="100%" justify="space-between" borderBottom="1px solid" borderColor="border" pb="16px">
                  <SingleTokenInfo symbolFontSize="16px" token={rewardInfo?.rewardCoin} />
                  <Text fontSize="20px" fontWeight="500" color="text_caption">
                    {rewardInfo?.rewardNum || '--'}
                  </Text>
                </HStack>

                <VStack mt="16px" gap="16px">
                  <HTextLabelBox
                    label="Start Time"
                    isLoading={false}
                    labelStyle={textStyle}
                    value={rewardInfo?.startIsNow ? 'Incentive Now' : timeFormatUTC(rewardInfo?.startTime || 0) + '(UTC)'}
                    valueStyle={textStyle}
                  />
                  <HTextLabelBox
                    label="End Time"
                    isLoading={false}
                    labelStyle={textStyle}
                    value={timeFormatUTC(rewardInfo?.endTime || 0) + '(UTC)'}
                    valueStyle={textStyle}
                  />
                  <HTextLabelBox
                    label="Epoch"
                    isLoading={false}
                    labelStyle={textStyle}
                    value={formatEpoch(rewardInfo?.startTime, rewardInfo?.endTime) as string}
                    valueStyle={textStyle}
                  />

                  <HStack w="100%" justify="space-between">
                    <HStack gap="4px">
                      <Text>Release Rate</Text>
                      <TooltipIcon tooltipCon="Release rate estimates how many rewards will be distributed per hour, based on its selected duration." />
                    </HStack>
                    <Text color="text_caption">
                      {rewardInfo?.releaseRate || '--'} {textEllipses(rewardInfo?.rewardCoin?.symbol, 10) || ''} per hour
                    </Text>
                  </HStack>
                </VStack>
              </Block>
            ))}
          </VStack>
          <HStack p="16px" w="100%" justify="space-between">
            <Text>Total Amount</Text>
            <Text>{totalAmount}</Text>
          </HStack>
          <Button m="0 16px" w="calc(100% - 32px)" h="48px" fontSize="18px" fontWeight="500">
            Confirm
          </Button>
        </ModalBody>
      </ModalContent>
    </Modal>
  )
}
