import { IncentiveRewardInfo } from '@/types/incentive'
import { ErrorTips, TooltipIcon, TradeInput } from '@cetus/design'
import { useGetTokenBalance } from '@cetus/hooks/src/useTokenBalance'
import { Icon } from '@cetus/ui-kit'
import { textEllipses } from '@cetus/utils'
import { Button, HStack, Text, VStack } from '@chakra-ui/react'
import TimeSelect from './TimeSelect'

interface RewardContentProps {
  index: number
  rewardListLength: number
  rewardInfo: IncentiveRewardInfo
  whiteTokenList: any
  deleteReward: (index: number) => void
  updateReward: (index: number, type: string, value: any, startIsNow?: boolean) => void
}
export default function RewardContent({ whiteTokenList, index, rewardListLength, rewardInfo, deleteReward, updateReward }: RewardContentProps) {
  const { balanceInfo } = useGetTokenBalance(rewardInfo?.rewardCoin)
  return (
    <VStack
      w="100%"
      align="flex-start"
      pb="20px"
      borderBottom={rewardListLength == index + 1 ? 'none' : '1px solid'}
      borderColor={rewardListLength && rewardListLength > 1 ? 'border' : 'transparent'}
    >
      <HStack w="100%" justify="space-between">
        <Text color="text_caption" h="20px" lineHeight="20px">
          Reward {index + 1}
        </Text>
        {rewardListLength && rewardListLength > 1 && (
          <HStack
            gap="2px"
            onClick={() => deleteReward(index)}
            sx={{ button: { color: 'text_paragraph' }, _hover: { button: { color: 'primary' }, svg: { fill: 'primary !important' } } }}
          >
            <Icon w="18px" h="18px" xlinkHref="#icon-icon_del" svgHover="primary" />
            <Button
              p="0"
              bg="none"
              border="none"
              _hover={{
                bg: 'none',
                border: 'none'
              }}
              variant="ghost"
              fontSize="14px"
              height="20px"
            >
              Delete
            </Button>
          </HStack>
        )}
      </HStack>

      <HStack w="100%" justify="space-between">
        <TimeSelect
          rewardInfo={rewardInfo}
          title="Start Time"
          fieldKey="startTime"
          onSelect={(date, startIsNow) => updateReward(index, 'startTime', date, startIsNow)}
        />
        <TimeSelect rewardInfo={rewardInfo} title="End Time" fieldKey="endTime" onSelect={date => updateReward(index, 'endTime', date)} />
      </HStack>
      <TradeInput
        value={rewardInfo?.rewardNum || ''}
        onChange={val => updateReward(index, 'rewardNum', val)}
        token={rewardInfo?.rewardCoin}
        placeholder="0.0"
        balance={balanceInfo?.balanceFormat || ''}
        selectable
        onTokenChange={val => updateReward(index, 'rewardCoin', val)}
        wrapStyle={{ height: '110px' }}
        whiteTokenList={whiteTokenList}
        isShowTokenListTab={false}
        isShowLabelTab={false}
        isShowHotList={false}
      />
      <HStack w="100%" justify="space-between">
        <HStack gap="4px">
          <Text>Release Rate</Text>
          <TooltipIcon tooltipCon="Release rate estimates how many rewards will be distributed per hour, based on its selected duration." />
        </HStack>
        <Text color="text_caption">
          {rewardInfo?.releaseRate || '--'} {textEllipses(rewardInfo.rewardCoin?.symbol, 10) || ''} per hour
        </Text>
      </HStack>
      {rewardInfo?.startTime && rewardInfo?.endTime && rewardInfo?.rewardNum && rewardInfo?.releaseRate == 0 && (
        <ErrorTips
          type="error"
          tipsFontSize="12px"
          tipsLineHeight="16px"
          tips="The reward rate is too low. Try shortening the epoch duration or increasing the reward amount"
        />
      )}
    </VStack>
  )
}
