import { IncentiveRewardInfo } from '@/types/incentive'
import { TooltipIcon } from '@cetus/design'
import { Icon } from '@cetus/ui-kit'
import { d, timeFormatUTC } from '@cetus/utils'
import { Button, HStack, Menu, MenuButton, MenuItem, MenuList, Text, VStack } from '@chakra-ui/react'

interface TimeSelectProps {
  title: string
  rewardInfo: IncentiveRewardInfo
  fieldKey: 'startTime' | 'endTime'
  onSelect: (val: string | number, startIsNow?: boolean) => void
}

function getTimeOptions(isEndTime: boolean): number[] {
  const now = new Date()
  const dayOfWeek = now.getUTCDay()
  const daysUntilNextMonday = (7 - dayOfWeek) % 7
  // 每周一 UTC时间00:00:00
  const nextMonday = new Date(Date.UTC(now.getUTCFullYear(), now.getUTCMonth(), now.getUTCDate() + daysUntilNextMonday, 0, 0, 0, 0))

  const base = isEndTime ? nextMonday.getTime() : Date.now()
  const length = isEndTime ? 25 : 26

  const futureDates = Array.from({ length }, (_, i) => {
    const weekOffset = isEndTime ? i + 1 : i
    const targetDate = new Date(nextMonday.getTime() + weekOffset * 7 * 24 * 60 * 60 * 1000)
    return targetDate.getTime()
  })

  return [base, ...futureDates.map(Math.floor)]
}

export default function TimeSelect({ title, rewardInfo, fieldKey, onSelect }: TimeSelectProps) {
  // selectedTime已经选择了时间
  const selectedTime = rewardInfo?.[fieldKey]
  const isEndTime = title === 'End Time'
  // 获取时间下拉列表
  const timeOptions = getTimeOptions(title === 'End Time')

  // 结束时间 - 开始时间 要大于等于60分钟 否则时间不可选择
  const isAllowSelect = (date: number): boolean => {
    if (!isEndTime || !rewardInfo?.startTime) return true
    return d(date)
      .minus(rewardInfo.startTime)
      .gte(60 * 60 * 1000)
  }

  return (
    <Menu isLazy placement="bottom-start">
      {({ onClose }) => (
        <>
          <MenuButton
            as={Button}
            variant="outline"
            h="48px"
            lineHeight="48px"
            w={{ base: '100%', lg: '50%' }}
            _hover={{ bg: 'bg_secondary' }}
            _active={{
              bg: 'bg_secondary',
              borderColor: 'token_active_border !important',
              boxShadow: '0px 0px 6px 0px #0067AD'
            }}
          >
            <HStack w="100%" justify="space-between">
              <Text color={selectedTime ? 'text_caption' : 'text_paragraph'}>
                {selectedTime ? (rewardInfo?.startIsNow && !isEndTime ? 'Incentive Now' : timeFormatUTC(selectedTime)) : title}
              </Text>
              <Icon xlinkHref="#icon-canlender" />
            </HStack>
          </MenuButton>

          <MenuList zIndex={9999} p="8px 0" w="234px">
            <VStack h="200px" overflow="auto" p="0px 4px 0 8px" gap="4px">
              {timeOptions.map((date, index) => {
                const allowSelect = isAllowSelect(date)
                return (
                  <MenuItem
                    key={date}
                    h="32px"
                    borderRadius="8px"
                    _hover={{ bg: allowSelect ? 'primary_opacity.10' : undefined }}
                    cursor={allowSelect ? 'pointer' : 'not-allowed'}
                    onClick={() => {
                      if (allowSelect) {
                        // startIsNow: index === 0 && !isEndTime
                        onSelect(date, index === 0 && !isEndTime)
                        onClose()
                      }
                    }}
                  >
                    <Text mr="4px" color="text_caption">
                      {index === 0 && !isEndTime ? 'Incentive Now' : timeFormatUTC(date)}
                    </Text>
                    {index === 0 && !isEndTime && <TooltipIcon tooltipCon="The reward will activate when the transaction is executed." />}
                  </MenuItem>
                )
              })}
            </VStack>
            <HStack p="8px 12px 2px" gap="4px">
              {/* <Icon xlinkHref="#icon-icon_tips" svgHover="text_paragraph" cursor="text" /> */}
              <Text fontSize="12px" w="100%">
                Times are in UTC
              </Text>
            </HStack>
          </MenuList>
        </>
      )}
    </Menu>
  )
}
